/* ===== LV MOTORSPORT — script.js ===== */

const SYSTEM = `Tu es l'agent LV Motorsport, assistant spécialisé en fabrication 3D pour le sport automobile. Tu représentes un étudiant en mécatronique passionné d'automobile. Produits : Boîtiers électroniques 60–150€ PETG/ASA, Gabarits 20–45€ PLA, Logos clubs 30–70€ PLA Silk, Plaques de box 25–55€, Figurines 80–180€, Trophées Digital 35€ / Imprimé 40–75€ / Premium 90–120€, Sim Racing : button box 25–130€, handbrake 40–80€, supports 15–40€, paddles 50–100€, hub volant 30–60€, support mural 25–45€, socle bureau 30–55€. Imprimante Bambu Lab P2S. Expédition France rapide. Réponds en 2-3 phrases max dans la langue de l'utilisateur.`;

let lang = 'fr', hist = [], busy = false;

/* ===== NAVIGATION ===== */
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('screen-' + id).classList.add('active');
  window.scrollTo(0, 0);
  triggerReveal();
}
function showCat(cat) { showScreen(cat); }

/* ===== LANGUAGE ===== */
function setLang(l) {
  lang = l;
  document.querySelectorAll('.lang-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.lang === l);
  });
  document.querySelectorAll('[data-fr]').forEach(el => {
    const val = el.getAttribute('data-' + l);
    if (!val) return;
    if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') el.placeholder = val;
    else if (el.tagName === 'OPTION' || el.tagName === 'OPTGROUP') { el.label = val; el.textContent = val; }
    else el.innerHTML = val;
  });
}

/* ===== SCROLL ===== */
function scrollTo2(id) {
  const el = document.getElementById(id);
  if (el) el.scrollIntoView({ behavior: 'smooth' });
}

/* ===== FILTER ===== */
function filterCat(cat, btn) {
  document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.product-card').forEach(c => {
    c.classList.toggle('hidden', cat !== 'all' && c.dataset.cat !== cat);
  });
}

/* ===== MOBILE MENU ===== */
function toggleMobileMenu() {
  const menu = document.getElementById('mobileMenu');
  const burger = document.getElementById('hamburger');
  menu.classList.toggle('open');
  burger.classList.toggle('open');
}
function closeMobileMenu() {
  document.getElementById('mobileMenu').classList.remove('open');
  document.getElementById('hamburger').classList.remove('open');
}

/* ===== AGENT ===== */
function toggleAgent() {
  document.getElementById('agentBody').classList.toggle('open');
  document.getElementById('chevron').classList.toggle('open');
}

function addMsg(role, text) {
  const area = document.getElementById('chatArea');
  const d = document.createElement('div');
  d.className = 'msg ' + (role === 'user' ? 'user' : 'bot');
  d.innerHTML = role === 'user'
    ? `<div class="msg-av">V</div><div class="msg-bubble">${text}</div>`
    : `<div class="msg-av">LV</div><div class="msg-bubble">${text}</div>`;
  area.appendChild(d);
  area.scrollTop = area.scrollHeight;
}

function addTyping() {
  const area = document.getElementById('chatArea');
  const d = document.createElement('div');
  d.className = 'msg bot'; d.id = 'typing';
  d.innerHTML = `<div class="msg-av">LV</div><div class="msg-bubble"><div class="typing-dots"><span></span><span></span><span></span></div></div>`;
  area.appendChild(d);
  area.scrollTop = area.scrollHeight;
}

function removeTyping() {
  const t = document.getElementById('typing');
  if (t) t.remove();
}

async function csend() {
  if (busy) return;
  const inp = document.getElementById('chatInp');
  const txt = inp.value.trim();
  if (!txt) return;
  inp.value = '';
  busy = true;
  document.getElementById('sendB').disabled = true;
  addMsg('user', txt);
  hist.push({ role: 'user', content: txt });
  addTyping();
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1000, system: SYSTEM, messages: hist })
    });
    const data = await r.json();
    const reply = data.content?.find(b => b.type === 'text')?.text || 'Erreur.';
    removeTyping(); addMsg('bot', reply);
    hist.push({ role: 'assistant', content: reply });
  } catch (e) { removeTyping(); addMsg('bot', 'Une erreur est survenue.'); }
  busy = false;
  document.getElementById('sendB').disabled = false;
}

function qsend(txt) {
  if (!document.getElementById('agentBody').classList.contains('open')) toggleAgent();
  document.getElementById('chatInp').value = txt;
  csend();
}

/* ===== FORM ===== */
async function submitForm() {
  const name = document.getElementById('fname').value.trim();
  const email = document.getElementById('femail').value.trim();
  const desc = document.getElementById('fdesc').value.trim();
  const product = document.getElementById('fproduct').value;
  const qty = document.getElementById('fqty').value;
  const budget = document.getElementById('fbudget').value;
  if (!name || !email || !desc) { alert('Veuillez remplir les champs obligatoires.'); return; }
  const btn = document.querySelector('.submit-btn');
  btn.disabled = true;
  const originalText = btn.textContent;
  btn.textContent = 'Envoi en cours...';
  try {
    const res = await fetch('https://formspree.io/f/xeenkwvn', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
      body: JSON.stringify({ name, email, product, quantity: qty, budget, message: desc })
    });
    if (res.ok) {
      const sm = document.getElementById('successMsg');
      sm.style.display = 'block';
      setTimeout(() => sm.style.display = 'none', 6000);
      document.getElementById('fname').value = '';
      document.getElementById('femail').value = '';
      document.getElementById('fdesc').value = '';
      document.getElementById('fqty').value = '';
      document.getElementById('fbudget').value = '';
    } else {
      alert("Erreur lors de l'envoi. Réessayez ou contactez directement par email.");
    }
  } catch(e) {
    alert('Erreur réseau. Vérifiez votre connexion.');
  } finally {
    btn.disabled = false;
    btn.textContent = originalText;
  }
}

/* ===== SCROLL REVEAL ===== */
function triggerReveal() {
  const ro = new IntersectionObserver(entries => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('visible'); ro.unobserve(e.target); } });
  }, { threshold: 0.07 });
  document.querySelectorAll('.reveal').forEach(el => { el.classList.remove('visible'); ro.observe(el); });
}
document.addEventListener('DOMContentLoaded', triggerReveal);

/* ===== THREE.JS HERO ===== */
