    const rm = new THREE.LineBasicMaterial({ color: 0xC0392B, transparent: true, opacity: 0.18 });
    [[0, 0, 0.45, 'g'], [1.2, -0.8, 0.38, 'r'], [-1.5, 0.5, 0.42, 'g'], [0.5, 1.0, 0.35, 'r'], [-0.8, -1.2, 0.4, 'g'], [1.8, 0.3, 0.32, 'g']].forEach(([ox, oy, sc, col]) => {
      const pts = [[-6, 2], [-4, 2], [-3, 3], [-1, 3], [0, 2], [2, 2], [3, 3], [5, 3], [6, 2], [6, 0], [5, -1], [3, -1], [2, 0], [0, 0], [-1, -1], [-3, -1], [-4, 0], [-6, 0], [-6, -2], [-4, -2], [-3, -3], [-1, -3], [0, -2], [2, -2], [3, -3], [5, -3], [6, -2]].map(([x, y]) => new THREE.Vector3((x + ox) * sc, (y + oy) * sc, -2.5));
      const g = new THREE.BufferGeometry().setFromPoints(pts);
      cg.add(new THREE.Line(g, col === 'r' ? rm : lm));
    });
    for (let i = 0; i < 14; i++) {
      const y = (Math.random() - .5) * 10, x = (Math.random() - .5) * 14, len = 2 + Math.random() * 4;
      const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(x, y, -4), new THREE.Vector3(x + len, y, -4)]);
      cg.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: i % 4 === 0 ? 0xC0392B : 0x1e1e1e, transparent: true, opacity: .15 + Math.random() * .15 })));
    }
    scene.add(cg);

    const gold = new THREE.MeshStandardMaterial({ color: 0xC9A84C, metalness: 0.92, roughness: 0.12 });
    const goldD = new THREE.MeshStandardMaterial({ color: 0x8A6A1F, metalness: 0.8, roughness: 0.28 });

    const tg = new THREE.Group();
    const base=new THREE.Mesh(new THREE.CylinderGeometry(0.7,0.9,0.25,32),gold);base.position.set(0,-1.5,0);tg.add(base);
    const stem=new THREE.Mesh(new THREE.CylinderGeometry(0.12,0.2,0.6,16),goldD);stem.position.set(0,-1.1,0);tg.add(stem);
    const sh = new THREE.Shape();
    sh.moveTo(0, -0.8); sh.bezierCurveTo(-0.3, -0.8, -0.5, -0.5, -0.5, -0.2); sh.bezierCurveTo(-0.5, 0.1, -0.2, 0.2, 0, 0.2); sh.bezierCurveTo(0.2, 0.2, 0.5, 0.3, 0.5, 0.6); sh.bezierCurveTo(0.5, 0.9, 0.2, 1.0, 0, 1.0); sh.bezierCurveTo(-0.2, 1.0, -0.4, 0.9, -0.4, 0.7);
