/* ===== 3D VIEWER MODAL ===== */
let viewerRenderer, viewerScene, viewerCamera, viewerControls, viewerRAF;
let currentViewerModel = null;

function openViewer(modelName, matLabel, glbPath) {
  document.getElementById('viewerOverlay').classList.add('open');
  document.getElementById('viewerTitleText').textContent = modelName;
  document.getElementById('viewerMatTag').textContent = matLabel;
  document.body.style.overflow = 'hidden';
  window._currentViewerGLB = glbPath || null;
  if (!viewerRenderer) initViewerRenderer();
  else loadDefaultModel(modelName, glbPath || null);
}

function closeViewer() {
  document.getElementById('viewerOverlay').classList.remove('open');
  document.body.style.overflow = '';
}

function initViewerRenderer() {
  if (typeof THREE === 'undefined') { setTimeout(initViewerRenderer, 300); return; }
  const canvas = document.getElementById('viewerCanvas');
  const wrap = canvas.parentElement;
  const W = wrap.clientWidth, H = wrap.clientHeight;
  viewerRenderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
  viewerRenderer.setSize(W, H);
  viewerRenderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  viewerRenderer.setClearColor(0x080808, 1);
  viewerScene = new THREE.Scene();
  viewerCamera = new THREE.PerspectiveCamera(45, W / H, 0.1, 200);
  viewerCamera.position.set(0, 2, 8);
  // Lights
  viewerScene.add(new THREE.AmbientLight(0xffffff, 0.4));
  const dl = new THREE.DirectionalLight(0xffd700, 1.2); dl.position.set(5, 8, 5); viewerScene.add(dl);
  const rl = new THREE.DirectionalLight(0xC0392B, 0.6); rl.position.set(-5, -2, -3); viewerScene.add(rl);
  const fl = new THREE.PointLight(0xffffff, 0.5, 40); fl.position.set(0, 6, 8); viewerScene.add(fl);
  // Grid
  const grid = new THREE.GridHelper(12, 12, 0x1a1a1a, 0x111111);
  grid.position.y = -2.5; viewerScene.add(grid);
  // OrbitControls (manual implementation — no import needed)
  setupOrbitControls(canvas);
  // Load default trophy
  if (window._currentViewerGLB) {
    loadGLBIntoViewer(window._currentViewerGLB);
  } else {
    currentViewerModel = buildTrophy3D(0xC9A84C);
    currentViewerModel.scale.set(1.5,1.5,1.5);
    viewerScene.add(currentViewerModel);
  }
  animateViewer();
  window.addEventListener('resize', resizeViewer);
}

function resizeViewer() {
  const wrap = document.getElementById('viewerCanvas').parentElement;
  if (!viewerRenderer || !wrap) return;
  const W = wrap.clientWidth, H = wrap.clientHeight;
  viewerCamera.aspect = W / H; viewerCamera.updateProjectionMatrix();
  viewerRenderer.setSize(W, H);
}

// GLB logo data for viewer
const _LOGO_GLB_B64 = '';

function loadGLBLogo(onLoaded) {
  if (typeof THREE.GLTFLoader === 'undefined') {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/loaders/GLTFLoader.js';
    s.onload = () => loadGLBLogo(onLoaded);
    document.head.appendChild(s);
    return;
  }
  const bin = Uint8Array.from(atob(_LOGO_GLB_B64), c => c.charCodeAt(0));
  const url = URL.createObjectURL(new Blob([bin], {type:'model/gltf-binary'}));
  new THREE.GLTFLoader().load(url, gltf => {
    const m = gltf.scene;
    const box = new THREE.Box3().setFromObject(m);
    const c = box.getCenter(new THREE.Vector3());
    const sz = box.getSize(new THREE.Vector3());
    const sf = 3.0 / Math.max(sz.x, sz.y, sz.z);
    m.position.sub(c);
    m.scale.set(sf, sf, sf);
    m.traverse(ch => { if(ch.isMesh) { ch.material.metalness = 0.8; ch.material.roughness = 0.15; } });
    URL.revokeObjectURL(url);
    onLoaded(m);
  }, undefined, e => { console.warn('GLB viewer error:', e); onLoaded(null); });
}

function loadGLBIntoViewer(glbPath) {
  if (currentViewerModel) { viewerScene.remove(currentViewerModel); currentViewerModel = null; }
  if (!THREE.GLTFLoader) return;
  new THREE.GLTFLoader().load(glbPath, function(gltf) {
    currentViewerModel = gltf.scene;
    const box = new THREE.Box3().setFromObject(currentViewerModel);
    const c = box.getCenter(new THREE.Vector3());
    const sz = box.getSize(new THREE.Vector3());
    const sf = 3.0 / Math.max(sz.x, sz.y, sz.z);
    currentViewerModel.position.set(0,0,0);
    currentViewerModel.scale.set(sf,sf,sf);
    const box2 = new THREE.Box3().setFromObject(currentViewerModel);
    const c2 = box2.getCenter(new THREE.Vector3());
    currentViewerModel.position.set(-c2.x,-c2.y,-c2.z);
    currentViewerModel.traverse(ch => {
      if(ch.isMesh){ ch.material.metalness=0.85; ch.material.roughness=0.12; ch.material.needsUpdate=true; }
    });
    viewerScene.add(currentViewerModel);
  }, undefined, e => console.warn('Viewer GLB error:', e));
}

function loadDefaultModel(name, glbPath) {
  if (glbPath) { loadGLBIntoViewer(glbPath); return; }
  if (currentViewerModel) { viewerScene.remove(currentViewerModel); currentViewerModel = null; }
  const n = name.toLowerCase();
  if (n.includes('trophée') || n.includes('trophy') || n.includes('rmt') || n.includes('gold') || n.includes('or')) {
    currentViewerModel = buildTrophy3D(0xC9A84C);
  } else if (n.includes('sim') || n.includes('bouton') || n.includes('button')) {
    currentViewerModel = buildBox3D(0x1A1A1A);
  } else if (n.includes('volant')) {
    currentViewerModel = buildSim3D(0xC0392B);
  } else {
    currentViewerModel = buildTrophy3D(0xC0392B);
  }
  currentViewerModel.scale.set(1.5,1.5,1.5);
  viewerScene.add(currentViewerModel);
}

// Orbit controls
let orbitState = { down: false, lastX: 0, lastY: 0, rotX: 0, rotY: 0, dist: 8, panX: 0, panY: 0 };
function setupOrbitControls(el) {
  el.addEventListener('mousedown', e => { orbitState.down = true; orbitState.lastX = e.clientX; orbitState.lastY = e.clientY; });
  window.addEventListener('mousemove', e => {
    if (!orbitState.down) return;
    orbitState.rotY += (e.clientX - orbitState.lastX) * 0.008;
    orbitState.rotX += (e.clientY - orbitState.lastY) * 0.008;
    orbitState.rotX = Math.max(-1.2, Math.min(1.2, orbitState.rotX));
    orbitState.lastX = e.clientX; orbitState.lastY = e.clientY;
  });
  window.addEventListener('mouseup', () => orbitState.down = false);
  el.addEventListener('wheel', e => { orbitState.dist = Math.max(3, Math.min(16, orbitState.dist + e.deltaY * 0.01)); });
  // Touch
  let lastTouch = null;
  el.addEventListener('touchstart', e => { lastTouch = e.touches[0]; });
  el.addEventListener('touchmove', e => {
    if (!lastTouch) return;
    orbitState.rotY += (e.touches[0].clientX - lastTouch.clientX) * 0.008;
    orbitState.rotX += (e.touches[0].clientY - lastTouch.clientY) * 0.008;
    lastTouch = e.touches[0];
    e.preventDefault();
  }, { passive: false });
}

function animateViewer() {
  viewerRAF = requestAnimationFrame(animateViewer);
  if (!viewerRenderer) return;
  const { rotX, rotY, dist } = orbitState;
  viewerCamera.position.x = dist * Math.sin(rotY) * Math.cos(rotX);
  viewerCamera.position.y = dist * Math.sin(rotX) + 0.5;
  viewerCamera.position.z = dist * Math.cos(rotY) * Math.cos(rotX);
  viewerCamera.lookAt(0, 0.5, 0);
  if (currentViewerModel && !orbitState.down) {
    currentViewerModel.rotation.y += 0.004;
  }
  viewerRenderer.render(viewerScene, viewerCamera);
}

// STL file loader
document.addEventListener('DOMContentLoaded', () => {
  const inp = document.getElementById('stlFileInput');
  if (inp) inp.addEventListener('change', e => {
    const file = e.target.files[0];
    if (!file || !file.name.endsWith('.stl')) return;
    document.getElementById('viewerModelName').textContent = file.name.replace('.stl','');
    const reader = new FileReader();
    reader.onload = ev => {
      if (!viewerRenderer) return;
      // STLLoader not available — use default model
      loadDefaultModel(file.name);
    };
    reader.readAsArrayBuffer(file);
  });
});

// Animated stat counters
function animateCounters() {
  document.querySelectorAll('.stat-num[data-target]').forEach(el => {
    const target = parseFloat(el.dataset.target);
    const prefix = el.dataset.prefix || '';
    const suffix = el.dataset.suffix || '';
    let current = 0;
    const step = target / 40;
    const timer = setInterval(() => {
      current = Math.min(current + step, target);
      el.textContent = prefix + (Number.isInteger(target) ? Math.round(current) : current.toFixed(0)) + suffix;
      if (current >= target) clearInterval(timer);
    }, 30);
  });
}

// Trigger counters on scroll into view
const statsObs = new IntersectionObserver(entries => {
  entries.forEach(e => { if (e.isIntersecting) { animateCounters(); statsObs.disconnect(); } });
}, { threshold: 0.4 });
document.addEventListener('DOMContentLoaded', () => {
  const sb = document.querySelector('.stats-bar');
  if (sb) statsObs.observe(sb);
});
